\begin{definition}[Bridge-defect equation]\label{def:apparatus:bridge-defect-equation}
After a comparison trivialization the strong-duality defect decomposes
additively,
\[
  \Delta_{\mathrm{BSD}}^{\mathrm{BK}}
  =E_{\mathrm{an/period}}+E_{\mathrm{ht/reg}}+E_{\mathrm{finite}}
   +\textstyle\sum_p E_p+E_{\det},
\]
(multiplicatively, the corresponding product of component ratios).
\end{definition}

\begin{nonclaim}\label{nonclaim:apparatus:decomposition-scope}
The decomposition does not prove BSD, Bloch--Kato, or ETNC; it proves a
component-map theorem and the public-shadow no-go, and classifies
framework-derived content versus the five external transports.
\end{nonclaim}

\begin{theorem}[Height tangent Schur collapse]\label{thm:apparatus:height-schur-collapse}
On $S_r=\operatorname{Sym}_r(\R)$, $x=\operatorname{vech}(\delta H)$, $C=I$,
with $L_{\mathrm{full}}(x)=x$ and $D_H(\delta H)=\tr(H^{-1}\delta H)=d_Hx$,
\[
  \XiC=d_Hd_H^{\mathsf T}-d_H I d_H^{\mathsf T}=0 .
\]
The pre-source residual is $K_{DD}=\|d_H\|^2$ (e.g.\ $37a1$: $382.79\ldots$);
rank-$0$ rows are vacuous ($K_{DD}=0$).
\end{theorem}

\begin{obligation}[Refined height-regulator BK transport]\label{obl:apparatus:rho-ht-reg-transport}
Construct an accepted bridge $\beta_{\mathrm{BK,ht}}:\det(V_E^*)\otimes
\det(V_E)^*\to\Delta_f(M_E)_{\mathrm{ht/reg}}$ identifying the Néron--Tate
determinant with the Beilinson/Deligne regulator normalization (coefficient
convention; archimedean Deligne-cohomology normalization; determinant
orientation; compatibility with the finite/det components). External content;
recognition source, not Lean-derived.
\end{obligation}

\begin{warning}[Carrier discipline for $571a1$]\label{warn:apparatus:571a1-carrier}
$571a1$ has Mordell--Weil rank $0$ with nontrivial $\Sha[2]$/Cassels--Tate
data; its lawful height-regulator row is rank-$0$/vacuous. Rank-$2$ instances
use $389a1$.
\end{warning}

\begin{theorem}[Analytic/period tangent Schur collapse]\label{thm:apparatus:analytic-period-schur-collapse}
With $x=(\log A_E,\log\Omega_E^+)\in\R^2$, $C=I_2$, $L_{\mathrm{full}}(x)=x$,
$D(x)=x_A-x_\Omega$ (row $d=(1,-1)$): $K_{LL}=I_2$, $K_{DD}=dd^{\mathsf T}=2$,
so $\XiC=2-dI_2d^{\mathsf T}=0$. (No source $\Rightarrow$ residual $2$; only
$x_A$ $\Rightarrow$ residual $1$; both $\Rightarrow0$.)
\end{theorem}

\begin{theorem}[Scalar finite projection (NG-1, Schur form)]\label{thm:apparatus:scalar-finite-shadow}
The scalar projection $q=s\cdot x$, $s=(1,-2,1,0)$, has projector
$P_s=s^{\mathsf T}(ss^{\mathsf T})^{-1}s$ and $\Xi_{\mathrm{scalar}}=I_4-P_s$
with $\tr(\Xi_{\mathrm{scalar}})=3>0$. Noninjectivity: $(0,0,2,H)$ and
$(2,0,0,0)$ both give $q=2$ in the $\Sha$-CT resp.\ Tamagawa block.
\end{theorem}

\begin{obligation}[Refined finite-source BK transport]\label{obl:apparatus:rho-finite-transport}
Construct $\beta_{\mathrm{BK,finite}}:\mathcal L_{\mathrm{finite}}(E)_{\R}\to
\Delta_f(M_E)_{\mathrm{finite}}$ (integral local-condition conventions at bad
primes; squared-torsion normalization; Cassels--Tate Pfaffian/orientation;
compatibility with $\rho_{\det}$). Recognition source.
\end{obligation}

\begin{obligation}[Integral determinant assembly]\label{obl:apparatus:rho-det-assembly}
Construct $\beta_{\det\text{-}\mathrm{assembly}}:(\Delta_{\mathrm{ht/reg}}
\otimes\Delta_{\mathrm{an/period}}\otimes\Delta_{\mathrm{finite}}\otimes
\bigotimes_p\Delta_p)\to\Delta_f(M_E)$ (Knudsen--Mumford signs; Selmer-complex
local-global compatibility; zeta vs.\ motivic trivialization; compatibility
with the four refined transports). Recognition source.
\end{obligation}

\begin{remark}[Five-column literature gap (support only; audit observation)]\label{rmk:apparatus:five-column-literature-gap}
A paper-grounded audit (Schneider 1988; Bloch--Kato 1990 \S5; Nekov\'a\v{r}
1994; b58 verdict mixed) records that the audited literature presents
$\Delta_f(M_E)$ as a single global Tamagawa-number package, with no typed
five-column decomposition. Relative to that corpus the b52a decomposition is a
structural contribution not found in the literature. Audit observation,
not a Lean-derivable theorem; not mechanized.
\end{remark}

\begin{definition}[Rank-2 Mordell--Weil/Kummer source]\label{def:apparatus:rank-two-kummer-source}
For $\Lambda_E=E(\Q)/E(\Q)_{\tors}$ and prime $p$, the Kummer map
$\kappa_p:\Lambda_E\otimes\Qp\to\Hf(\Q,V_p(E))$ gives, on a MW basis
$(P_1,P_2)$ of $389a1$, the rank-$2$ candidate $c_2^{\mathrm{MW}}(P_i)=
\kappa_p(P_i)$. Classical once the basis is known; not a motivic-cycle source.
\end{definition}

\begin{theorem}[Rank-2 height Schur collapse]\label{thm:apparatus:rank-two-height-schur-collapse}
For the $389a1$ Gram representative with $d(\log\det)_H=\ell=(3.12679\ldots,
-0.76771\ldots,2.14483\ldots)$, $K_{LL}=I_3$, $K_{DD}=\|\ell\|^2=14.96650\ldots$:
$\Xi=\|\ell\|^2-\ell I_3\ell^{\mathsf T}=0$. The scalar-determinant-only source
leaves residual $3-1=2$.
\end{theorem}

\begin{theorem}[Finite-window promotion no-go (NG-4)]\label{thm:apparatus:finite-window-no-go}
For $C_{\mathrm{BSD}}^{\mathrm{typed},+}=\operatorname*{colim}_{N_0\to\infty}
\{E/\Q:\operatorname{cond}(E)\leq N_0\}$, no theorem-grade promotion from the
b50 five-curve window $W_{50}$ to $\forall E/\Q,\mathrm{BSD}(E)$ can depend only
on $W_{50}$: at bound $B$ with $M(B)=\#C_{\mathrm{BSD}}(B)$, $K_{LL}=I_5$,
$K_{DD}=I_{M(B)}$, $\tr\Xi_B=M(B)-5\to\infty$. Two completions agreeing on
$W_{50}$ but differing at any $E_*\notin W_{50}$ are indistinguishable to a
$W_{50}$-only operator.
\end{theorem}

\begin{theorem}[Finite-prime cover no-go (NG-5)]\label{thm:apparatus:finite-prime-cover-no-go}
No fixed finite prime set certifies the all-prime support-prime carrier
$\bigotimes_p\Delta_f(M_E)_p$: for any finite $P_0$, choose $q\notin P_0$; two
completions agreeing on $P_0$ but assigning $q$ a covered vs.\ uncovered local
row are indistinguishable to a $P_0$-only operator.
\end{theorem}

\begin{definition}[Support-prime truncation residual (finite diagnostic)]\label{def:apparatus:support-prime-truncation-residual}
For $S_B=\{p\leq B\}$, with each R4b row one unit of unexplained local data,
$\Xi_B(E)=u_B(E)$ (the number of R4b rows in $S_B$). A finite diagnostic,
distinct from \Cref{thm:apparatus:finite-prime-cover-no-go}. b50 values below
$50$: $\Xi(11a1)=\Xi(37a1)=\Xi(121b1)=1$, $\Xi(960d1)=3$, $\Xi(571a1)=0$.
\end{definition}

\begin{definition}[Virtual source algebra]\label{def:apparatus:vsrc-algebra}
For $E/\Q$ of rank $r$, $V_r=\Q J_1\oplus\cdots\oplus\Q J_r$,
$\mathrm{vsrc}_r(E)=\Lambda_{\Q}(V_r)$ with $J_i^2=0$, $J_iJ_j=-J_jJ_i$
($i\neq j$), unit $1$; each $J_i$ a non-descending virtual independent
motivic-cycle source class.
\end{definition}

\begin{definition}[Imported $\chi_{CT,p}$ theorem stack]\label{def:closure:chi-ct-p-import}
A proof-carrying structure bundling the eight named external theorems
$T_{E1}\ldots T_{E8}$ (Sakamoto; Macias--Sano Thm 4.7(v); Knudsen; Nekov\'a\v{r}
Ast\'erisque 310 \S10.8.7; Flach 1990; FSS Thm 5.2; \ldots) as $\mathrm{Prop}$
fields, plus the unconditional sign closure $\Sigma_{\mathrm{NekCT}}=+1$. Taken
as a hypothesis by \Cref{thm:closure:chi-ct-p-comparison}; not derived.
\end{definition}

\begin{definition}[Imported $A_E$ Selmer-complex pairing]\label{def:closure:a-e-import}
A proof-carrying structure for the $A_E$ unified Selmer-complex substrate
(Nekov\'a\v{r} Selmer complex with intrinsic Cassels--Tate pairing;
Burns--Flach--Macias-Sano--Nekov\'a\v{r} ETNC-adjacent $A_E^{\mathrm{Sel}}$): a
typed target category with a bilinear/categorical pairing field. Hypothesis only.
\end{definition}

\begin{definition}[Imported Beilinson rank-$\geq 2$ comparison]\label{def:closure:beilinson-import}
A proof-carrying structure for the Beilinson determinant / $L$-value comparison
in rank $r\geq 2$ (archimedean regulator-to-determinant-line identification used
by the rank-$\geq 2$ landing). Hypothesis only.
\end{definition}

\begin{nonclaim}\label{nonclaim:closure:imports-not-derived}
The import structures are sourced assumptions, not framework theorems; the
closure derives consequences \emph{from} them and never proves them, and they
carry no project-local axioms.
\end{nonclaim}

\begin{nonclaim}\label{nonclaim:closure:recognition-sources-not-derived}
Each $\Gamma_{\mathrm{BSD}}^{*}$ is formed-layer closure content named as an
accepted recognition source, not framework-primitive derivable; in Lean the
carrier is mechanized but its $\mathrm{Prop}$ content is a hypothesis, never an
axiom. Each records a $(ii)/(iii)/(ii)$ Stage-6 trace signature.
\end{nonclaim}

\begin{theorem}[Master-theorem applicability]\label{thm:closure:master-theorem-applicability}
The closure master-theorem applies to $\Sel^{!}_{\mathrm{BSD}}$ via the
Foundations-IV applicability audit of the recognition sources' instantiations
(F2/F3/F4, F19/F21/F29, F14/F27/F40), and the smuggle audit passes (no
out-of-scope content is silently used as a derivation target).
\end{theorem}

\begin{definition}[OC $\eta$ published imports]\label{def:closure:eta-published-imports}
A proof-carrying structure with the distinct imports kept separate: Bella\"iche
Lemma 3.21; Pollack--Stevens 2011; arXiv:2403.16076; Lang--Wake 2025
(arXiv:2501.04162, distinct from arXiv:2403.16076); Lorenzini 1995; Ling 1997;
plus the single cascade-internal conjecture
$C_{B691}$ (cuspidal-layer evaluation nonzero and primitive).
\end{definition}

\begin{theorem}[$T_{\mathrm{BAD}\_\mathrm{REFINED}}$ typed no-go]\label{thm:closure:t-bad-no-go}
No theorem-grade direct additive-prime IMC exists in the audited Mode A
literature for $E/\Q$ additive at $p\in\{2,3\}$ with explicit local correction
factors and characteristic-ideal equality. Four sub-residuals (R\_BAD\_a..d) +
Kodaira HPS2 screen. Audit-result typed no-go.
\end{theorem}

\begin{remark}[Mode-B binding residuals]\label{rmk:closure:mode-b-residuals}
The Mode-B residuals $D_2''$ (vahb$_r$ rank-$r$ open), $D_2'''$ (signed-Selmer
corestriction), $D_3'''$ (p-adic $L$ norm identity) are the cascade-internal
reorganizations that the recognition sources of \S2 discharge; support-only
typed-open content.
\end{remark}

\begin{nonclaim}\label{nonclaim:closure:landing-conditional}
This is not an unconditional classical proof of BSD; it is theorem-grade within
the Six Birds closure discipline, conditional on the named recognition sources
and imports. $T_{E12\_\mathrm{REFINED}}$ (rank-$\geq2$ GZ) and
$T_{\mathrm{BAD}\_\mathrm{REFINED}}$ (additive $p\leq3$ IMC) remain open.
\end{nonclaim}

\begin{theorem}[Mechanical-record discharges]\label{thm:closure:aor-mechanical-records}
The mechanical membership components discharge \texttt{by\_construction} /
\texttt{approved\_other}: the $\Sel^{!}_{\mathrm{BSD}}$ construction and
$\kappa_r$ normalization (\texttt{by\_construction}); the
$\chi_{CT,p}$/$A_E$/Beilinson import structures as an \texttt{approved\_other}
external-record citation chain.
\end{theorem}

\begin{remark}[AOR partial status]\label{rmk:closure:aor-partial-status}
The AOR-instance reading does not close the open obligations; it records that the
BSD carrier is audit-closed under the declared refinement-stable AOR
presentation, with the recognition records reclassified rather than discarded.
\end{remark}
